(function(root){
  const normalize = s => String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
  function distance(a,b){let prev=null,row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++){next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])next[j]=Math.min(next[j],prev[j-2]+1);}prev=row;row=next;}return row[b.length];}
  const seeds=['Spider-Man','Batman','Superman','Iron Man','The Avengers','Harry Potter','Interstellar','Inception','Stranger Things','Breaking Bad','Game of Thrones','Money Heist','The Witcher','Squid Game','Wednesday','Dangal','Sholay','Baahubali','Pushpa','Drishyam','3 Idiots','Demon Slayer','One Piece','Attack on Titan'];
  function correct(query,titles=[]){const key=normalize(query);if(key.length<5||key.length>80)return query;const candidates=[...new Set([...seeds,...titles])];if(candidates.some(t=>normalize(t)===key))return candidates.find(t=>normalize(t)===key);let best=null,score=Infinity;for(const t of candidates){const n=normalize(t);if(Math.abs(n.length-key.length)>2)continue;const d=distance(key,n);if(d<score){score=d;best=t;}}return score<=Math.min(2,Math.floor(key.length/5))?best:query;}
  function eventData(raw){try{let d=typeof raw==='string'?JSON.parse(raw):raw;if(!d||typeof d!=='object')return null;if(d.type==='PLAYER_EVENT'&&d.data)d=typeof d.data==='string'?JSON.parse(d.data):d.data;return ['timeupdate','play','pause','ended'].includes(d.event)&&Number.isFinite(d.currentTime)&&d.currentTime>=0?d:null;}catch{return null;}}
  function progress(previous,film,d,season,episode){const s=Number(d.season??d.seasonNumber),e=Number(d.episode??d.episodeNumber);return {film,time:Math.floor(d.currentTime),duration:Number.isFinite(d.duration)&&d.duration>0?d.duration:0,season:Number.isInteger(s)&&s>0?s:season,episode:Number.isInteger(e)&&e>0?e:episode,updated:Date.now(),completed:d.event==='ended'||(d.duration>0&&d.currentTime/d.duration>=.97)};}
  const api={normalize,distance,correct,eventData,progress};if(typeof module!=='undefined')module.exports=api;else root.RadhaCore=api;
})(typeof window==='undefined'?globalThis:window);
